using System.Collections.Generic;

public static class Pruner
{
    // Remove all even numbers, keep the odds in order.
    // BUG: mutating the list during foreach throws InvalidOperationException.
    public static List<int> RemoveEvens(List<int> items)
    {
        foreach (var x in items)
        {
            if (x % 2 == 0)
            {
                items.Remove(x);
            }
        }
        return items;
    }
}

