using System.Collections.Generic;
using Xunit;

public class PrunerTests
{
    [Fact]
    public void RemovesEvensKeepsOddOrder()
    {
        Assert.Equal(new List<int> { 1, 3, 5 }, Pruner.RemoveEvens(new List<int> { 1, 2, 3, 4, 5 }));
    }

    [Fact]
    public void HandlesConsecutiveEvens()
    {
        Assert.Equal(new List<int> { 1, 5 }, Pruner.RemoveEvens(new List<int> { 2, 2, 1, 4, 6, 5 }));
    }

    [Fact]
    public void AllEvenBecomesEmpty()
    {
        Assert.Equal(new List<int>(), Pruner.RemoveEvens(new List<int> { 2, 4, 6 }));
    }

    [Fact]
    public void NoneEvenUnchanged()
    {
        Assert.Equal(new List<int> { 1, 3 }, Pruner.RemoveEvens(new List<int> { 1, 3 }));
    }
}

