using System.Collections.Generic;

public static class Pruner
{
    // Stops throwing but removes the ODD numbers instead of the even ones.
    public static List<int> RemoveEvens(List<int> items)
    {
        items.RemoveAll(x => x % 2 != 0);
        return items;
    }
}
